package com.smartlibrary.algorithms.string;import java.util.*;
public final class ZFunction {private ZFunction(){}public record Result(List<Integer> positions,int[] z,long comparisons){}public static Result search(String text,String pattern){if(text==null||pattern==null)throw new IllegalArgumentException();if(pattern.isEmpty())return new Result(java.util.stream.IntStream.rangeClosed(0,text.length()).boxed().toList(),new int[0],0);String s=pattern+Character.toString((char)0)+text;int[] z=new int[s.length()];int l=0,r=0;long c=0;for(int i=1;i<s.length();i++){if(i<=r)z[i]=Math.min(r-i+1,z[i-l]);while(i+z[i]<s.length()){c++;if(s.charAt(z[i])==s.charAt(i+z[i]))z[i]++;else break;}if(i+z[i]-1>r){l=i;r=i+z[i]-1;}}List<Integer> p=new ArrayList<>();for(int i=pattern.length()+1;i<s.length();i++)if(z[i]>=pattern.length())p.add(i-pattern.length()-1);return new Result(p,z,c);}}
